    def __init__(self, root, transform=None):
        # Initialize parent class first
        super(ImageFolder, self).__init__(root, transform=transform, loader=self.safe_loader)
        self.extensions = ImageFolder.IMG_EXTENSIONS

        # Walk the directory to find all image files
        samples = []
        dir = os.path.expanduser(root)
        for target in sorted(os.listdir(dir)):
            d = os.path.join(dir, target)
            if not os.path.isdir(d):
                continue
            for root, _, fnames in sorted(os.walk(d)):
                for fname in sorted(fnames):
                    if is_image_file(fname):
                        path = os.path.join(root, fname)
                        samples.append((path, self.class_to_idx[target]))

        # Filter out corrupted images
        valid_samples = []
        for path, class_idx in samples:
            try:
                # Try to actually load the image to verify it's valid
                from PIL import Image
                img = Image.open(path)
                img.load()  # Force load the image
                valid_samples.append((path, class_idx))
            except Exception as e:
                # Skip corrupted images
                pass

        self.samples = valid_samples
        self.imgs = self.samples

    def safe_loader(self, path):
        from PIL import Image
        with open(path, 'rb') as f:
            img = Image.open(f)
            return img.convert('RGB')

